// Generated shell pins and embedded safe extractor must match canonical sources.
import fs from 'node:fs';
const dir=new URL('./',import.meta.url), manifest=JSON.parse(fs.readFileSync(new URL('manifest.json',dir)));
const parser=fs.readFileSync(new URL('archive.mjs',dir),'utf8');
const shell=`#!/bin/sh
# Generated by generate-bootstrap.mjs; do not edit pins or extractor here.
set -eu
usage() { echo 'Usage: bootstrap.sh [--with-humanlayer] [--skills=all|none|compound,firecrawl,matt-pocock] [--yes] [<commit> <archive-sha256> | --checkout <directory> [--test | --export <destination>]]'; }
fail() { echo "$*" >&2; usage >&2; exit 2; }
option= skills= yes=
if [ "\${1:-}" = --help ]; then usage; exit 0; fi
while [ "$#" -gt 0 ]; do
 case "$1" in
 --with-humanlayer) option=$1;;
 --skills=*) skills=$1;;
 --yes) yes=$1;;
 *) break;;
 esac
 shift
done
checkout= testmode= exportdest=
if [ "$#" -eq 0 ]; then
 case "$0" in */*) checkout=$(CDPATH= cd -- "\${0%/*}" && pwd) || fail 'Cannot locate script directory';; *) fail 'Piped installation requires an explicit pinned commit and archive checksum.';; esac
elif [ "$1" = --checkout ]; then
 [ "$#" -ge 2 ] && [ -n "$2" ] || fail 'Missing checkout directory'
 checkout=$2; shift 2
 if [ "\${1:-}" = --test ]; then testmode=1; shift
 elif [ "\${1:-}" = --export ]; then
  [ "$#" -ge 2 ] && [ -n "$2" ] || fail 'Missing export destination'
  exportdest=$2; shift 2
 fi
 [ "$#" -eq 0 ] || fail 'Unexpected checkout arguments'
else
 [ "$#" -eq 2 ] || fail 'Expected commit and archive checksum'
 commit=$1 checksum=$2
 case "$commit$checksum" in *[!0-9a-f]*) fail 'Commit and checksum must be lowercase hexadecimal';; esac
 [ \${#commit} -eq 40 ] && [ \${#checksum} -eq 64 ] || fail 'Expected 40-character commit and 64-character checksum'
fi
if [ -n "$checkout" ]; then
 [ -f "$checkout/install.mjs" ] && [ -f "$checkout/manifest.json" ] || fail 'Not a bootstrap checkout'
fi
case "$(uname -s)" in Linux) platform=linux;; Darwin) platform=darwin;; *) fail "Unsupported platform or architecture";; esac
case "$(uname -m)" in x86_64) arch=x64;; arm64|aarch64) arch=arm64;; *) fail "Unsupported platform or architecture";; esac
case "$platform-$arch" in
${Object.entries(manifest.node).map(([key,value])=>` ${key}) digest=${value};;`).join('\n')}
 *) fail "Unsupported platform or architecture";;
esac
verify() {
 if command -v sha256sum >/dev/null 2>&1; then actual=$(sha256sum "$1"); else actual=$(shasum -a 256 "$1"); fi
 actual=\${actual%% *}; [ "$actual" = "$2" ] || { echo 'Checksum mismatch' >&2; exit 1; }
}
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT HUP INT TERM
echo '[bootstrap] Downloading pinned Node runtime (bounded to 900 seconds)' >&2
curl --connect-timeout 30 --max-time 900 --fail --progress-bar --show-error --location --proto '=https' --tlsv1.2 "https://nodejs.org/dist/v${manifest.nodeVersion}/node-v${manifest.nodeVersion}-$platform-$arch.tar.gz" -o "$tmp/node.tgz"
echo '[bootstrap] Verifying and extracting Node runtime' >&2
verify "$tmp/node.tgz" "$digest"
# Only the exact publisher-pinned Node archive reaches system tar, in an empty directory.
mkdir "$tmp/runtime"
tar -xzf "$tmp/node.tgz" -C "$tmp/runtime" --no-same-owner --no-same-permissions
node="$tmp/runtime/node-v${manifest.nodeVersion}-$platform-$arch/bin/node"
if [ -z "$checkout" ]; then
 curl --connect-timeout 30 --max-time 900 --fail --progress-bar --show-error --location --proto '=https' --tlsv1.2 "https://codeload.github.com/dapp-whisperer/pi-config/tar.gz/$commit" -o "$tmp/source.tgz"
 verify "$tmp/source.tgz" "$checksum"
 mkdir "$tmp/source"
 "$node" --input-type=module - "$tmp/source.tgz" "$tmp/source" <<'JS'
${parser}
unpack(process.argv[2],process.argv[3],{regularOnly:true});
JS
 checkout="$tmp/source/pi-config-$commit"
fi
if [ -n "$exportdest" ]; then "$node" "$checkout/export.mjs" "$exportdest"; elif [ -n "$testmode" ]; then "$node" --test "$checkout/test_first_run.mjs" "$checkout/test_safety.mjs" "$checkout/test_humanlayer_auto_advance.mjs" "$checkout/tests.mjs"; else "$node" "$checkout/install.mjs" \${option:+"$option"} \${skills:+"$skills"} \${yes:+"$yes"}; fi
`;
const target=new URL('bootstrap.sh',dir);
if(process.argv.includes('--check')) {if(fs.readFileSync(target,'utf8')!==shell) throw Error('Stale bootstrap.sh');} else fs.writeFileSync(target,shell,{mode:0o755});
